  <h3>Broken Links Found</h3>
  <ul>${brokenLinks.length ? brokenLinks.map(b => `<li>${b.broken_url} (status ${b.status_code})</li>`).join('') : '<li>None found 🎉</li>'}</ul>
`;

return [{ json: { reportHtml: html } }];

